with valid_products as (select * from products where category in ('Electronics', 'Home') and product_name is not null and brand not in ('Umbrella', 'Initech', 'Globex')), products_stats as (select brand, month(launch_date) as launch_month, concat_ws(', ', sort_array(collect_set(category))) as category_values, max(launch_date) as latest_launch_date from valid_products group by brand, month(launch_date)) select brand, launch_month, category_values, latest_launch_date from products_stats order by category_values desc;
